local FG = SuggestTab:AddRightGroupbox("建议 / 帮助", "message-square")
FG:AddDropdown("FeedbackType", { Text = "类型", Values = { "Suggestion", "Bug", "Help" }, Default = "Suggestion", Callback = function() end })
FG:AddInput("FeedbackMsg", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = "消息", Placeholder = "输入你的消息（最多 500 字符，不含链接）" })
local fbStatus = FG:AddLabel("", true)
local FEEDBACK_COOLDOWN, lastFeedback = 20, 0
FG:AddButton({
    Text = "发送",
    Func = function()
        local now = tick()
        if now - lastFeedback < FEEDBACK_COOLDOWN then
            pcall(function() fbStatus:SetText(string.format("请等待 %d 秒后再发送。", math.ceil(FEEDBACK_COOLDOWN - (now - lastFeedback)))) end)
            return
        end
        local ftype = tostring((Opt.FeedbackType and Opt.FeedbackType.Value) or "Suggestion"):lower()
        local msg = fbTrim((Opt.FeedbackMsg and Opt.FeedbackMsg.Value) or "")
        if msg == "" then pcall(function() fbStatus:SetText("消息为空。") end); return end
        if #msg > 500 then pcall(function() fbStatus:SetText("消息太长（最多 500 字符）。") end); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
            pcall(function() fbStatus:SetText("不允许链接。") end); return
        end
        pcall(function() fbStatus:SetText("发送中...") end)
        task.spawn(function()
            local sok, err = sendFeedback(ftype, msg)
            if sok then
                lastFeedback = tick()
                pcall(function() fbStatus:SetText("已发送。谢谢！") end)
                pcall(function() Opt.FeedbackMsg:SetValue("") end)
                log("你的反馈已发送。谢谢！")
            else
                pcall(function() fbStatus:SetText(FB_ERRMAP[err] or ("发送失败: " .. tostring(err))) end)
            end
        end)
    end,
})
FG:AddLabel("每小时最多 3 条消息。禁止链接或提及。", true)

freeBuy = Toggles.s_freebuy and Toggles.s_freebuy.Value ~= false
installActionHook()

SaveManager:SetLibrary(Library)
ThemeManager:SetLibrary(Library)
SaveManager:IgnoreThemeSettings()
SaveManager:SetIgnoreIndexes({ "s_menu", "FeedbackType", "FeedbackMsg" })
ThemeManager:SetFolder("KaijuAlphaSpoof")
SaveManager:SetFolder("KaijuAlphaSpoof")
ThemeManager:ApplyToTab(Tab)
SaveManager:BuildConfigSection(Tab)
SaveManager:LoadAutoloadConfig()

log("Spoofer 已加载")
